from dataclasses import dataclass, field


@dataclass
class Pregunta:
    texto: str
    tablas: list[str]
    grafica: str = ""


@dataclass
class PlanProyecto:
    tema: str
    fuente: str
    preguntas: list[Pregunta] = field(default_factory=list)

    def tablas_necesarias(self) -> list[str]:
        return sorted({t for p in self.preguntas for t in p.tablas})

    def revisar(self) -> list[str]:
        problemas = []
        if not 5 <= len(self.preguntas) <= 8:
            problemas.append(f"tiene {len(self.preguntas)} preguntas; deben ser de 5 a 8")
        if not any(p.grafica for p in self.preguntas):
            problemas.append("ninguna pregunta tiene gráfica")
        if not any(len(p.tablas) >= 2 for p in self.preguntas):
            problemas.append("ninguna pregunta necesita unir tablas")
        for p in self.preguntas:
            if not (p.texto.startswith("¿") and p.texto.endswith("?")):
                problemas.append(f"no es una pregunta: {p.texto!r}")
        return problemas


plan = PlanProyecto("Primera División de fútbol", "resultados publicados de cada jornada", [
    Pregunta("¿Qué equipo sumó más puntos en el torneo?", ["equipos", "partidos"], "barras"),
    Pregunta("¿Cuántos goles por partido hubo en cada jornada?", ["partidos"], "líneas"),
    Pregunta("¿Qué equipos ganan más de local que de visita?", ["equipos", "partidos"]),
    Pregunta("¿Quién es el goleador de cada equipo?", ["goles", "jugadores", "equipos"]),
    Pregunta("Analizar los goles", ["goles"]),
])
print("Tablas:", plan.tablas_necesarias())
for problema in plan.revisar():
    print("Revisar:", problema)

