def entero_o_nulo(texto):
    """Convierte ' 1500 ' en 1500 y '' en None."""
    texto = texto.strip().replace(" ", "")
    return int(texto) if texto else None


for valor in [" 1500 ", "12 500", "", "  "]:
    print(repr(valor), "->", entero_o_nulo(valor))

